suppressPackageStartupMessages({library(data.table);library(GenomicRanges);library(rtracklayer);library(ggplot2)})
set.seed(260923); options(warn=1)
out='output/external_rbp_splice_comparison/';perm=500L
savep=function(x,n,w=10,h=11){for(e in c('png','pdf'))ggsave(paste0(out,n,'.',e),x,width=w,height=h,dpi=220)}
chainpath='data/reference_followup/hg19ToHg38.over.chain';if(!file.exists(chainpath)){con=gzfile(paste0(chainpath,'.gz'),'rt');writeLines(readLines(con),chainpath);close(con)};chain=import.chain(chainpath)
files=c(QKI='PARCLIP_QKI_Hafner2010c_hg19',PUM2='PARCLIP_PUM2_Hafner2010b_hg19',ELAVL1='PARCLIP_ELAVL1A_hg19');sets=list();qc=list();source=list()
for(rbp in names(files)){
 path=paste0('data/external_rbp_controls/original/',files[rbp],'.bed');b=fread(path,header=FALSE);setnames(b,c('chrom','start','end','name','score','strand'));b[,peak_id:=paste0(rbp,'_',seq_len(.N))];valid=b$end>b$start & b$start>=0 & b$strand%in%c('+','-');bg=GRanges(b$chrom[valid],IRanges(b$start[valid]+1,b$end[valid]),b$strand[valid]);z=liftOver(bg,chain);nl=lengths(z);ix=which(nl==1);u=unlist(z[ix]);ratio=width(u)/width(bg)[ix];good=ratio>=.95 & ratio<=1.05;keep=ix[good];u=u[good];sel=b[which(valid)[keep]];new=data.table(peak_id=sel$peak_id,chrom=as.character(seqnames(u)),start=start(u)-1L,end=end(u),strand=as.character(strand(u)));new[,center:=floor((start+end-1)/2)];new[,localization:='interval midpoint'];sets[[rbp]]=new
 fwrite(new,paste0('data/external_rbp_controls/processed/',rbp,'_hg38.tsv'),sep='\t');export(GRanges(new$chrom,IRanges(new$start+1,new$end),new$strand),paste0('data/external_rbp_controls/processed/',rbp,'_hg38.bed'))
 qc[[rbp]]=data.table(RBP=rbp,original_N=nrow(b),malformed=sum(!valid),unmapped=sum(nl==0),split_or_multiple=sum(nl>1),width_QC_rejected=sum(!good),retained_N=nrow(new),percent_retained=100*nrow(new)/nrow(b),chain=chainpath,rule='Exactly one mapped interval; 95-105% original width; strand retained or flipped by chain')
 source[[rbp]]=data.table(RBP=rbp,publication=if(rbp=='ELAVL1')'Kishore et al. 2011' else 'Hafner et al. 2010',PMID=if(rbp=='ELAVL1')'21572407' else '20371350',method='PAR-CLIP',cell_line='HEK293',original_build='hg19',source='doRiNA original archived coordinates',filename=basename(path),original_N=nrow(b),coordinate_definition=if(rbp=='ELAVL1')'Archived BED intervals; precise cluster-generation details absent from JSON' else 'PCP contiguous pooled-library read-coverage clusters, per archived metadata',url=paste0('https://dorina.mdc-berlin.de/regulators/h_sapiens/hg19/',files[rbp],'.bed'),selection_reason=if(rbp=='ELAVL1')'Exact requested archived ELAVL1A; JSON explicitly identifies Kishore2011; library subset not specified' else 'Exact requested historical doRiNA dataset')
}
a=fread('data/results/peak_analysis/figures/all_nonzero_peaks/transcript_region_bias/peak_transcript_region_annotations.tsv');p=fread('data/results_round2/reference_peaks/peaks.tsv');m=merge(p,a,by='peak_id');sets=c(list(MSI2=data.table(peak_id=m$peak_id,chrom=m$summit_chromosome,start=m$start_0based,end=m$end_0based_exclusive,strand=m$summit_strand,center=m$summit_start_0based,localization='highest-score source omniCLIP summit')),sets)
fwrite(rbindlist(qc),paste0(out,'liftover_qc.tsv'),sep='\t');fwrite(rbindlist(source),paste0(out,'DATA_SOURCES.tsv'),sep='\t')
regions=fread('output/followup_analysis/cache/gencode_region_segments.tsv.gz');regions[,length:=end-start];regions[,priority:=match(category,c('CDS','5UTR','3UTR','intron','noncoding_exon'))];rg=GRanges(regions$chrom,IRanges(regions$start+1,regions$end),regions$strand)
land=fread('data/results/landmark_sites.tsv.gz');land=land[grepl('donor|acceptor',site_type)];land[,type:=ifelse(grepl('donor',site_type),'donor','acceptor')];stopifnot(nrow(land)>500000)
anchor=list();for(t in c('donor','acceptor')){ll=land[type==t];anchor[[t]]=split(ll$anchor_0based,paste(ll$chromosome,ll$strand));anchor[[t]]=lapply(anchor[[t]],sort)}
nearest=function(pos,chrom,str,t){ans=rep(Inf,length(pos));grp=split(seq_along(pos),paste(chrom,str));for(g in names(grp)){i=grp[[g]];an=anchor[[t]][[g]];if(!length(an))next;k=findInterval(pos[i],an);left=an[pmax(1,k)];right=an[pmin(length(an),k+1L)];near=ifelse(abs(pos[i]-left)<=abs(pos[i]-right),left,right);ans[i]=(pos[i]-near)*ifelse(str[i]=='+',1,-1)};ans}
profiles=list();enrich=list();prox=list();zones=list();elig=list()
for(rbp in names(sets)){
 message('External/background ',rbp);d=sets[[rbp]];pg=GRanges(d$chrom,IRanges(d$center+1,width=1),d$strand);h=suppressWarnings(findOverlaps(pg,rg));hit=data.table(pi=queryHits(h),ri=subjectHits(h));hit[,`:=`(priority=regions$priority[ri],len=regions$length[ri],gene=regions$gene_id[ri])];setorder(hit,pi,priority,-len,gene,ri);hit=hit[!duplicated(pi)];setorder(hit,pi);z=d[hit$pi];z[,`:=`(region=regions$category[hit$ri],gene_id=regions$gene_id[hit$ri],null_start=regions$start[hit$ri],null_end=regions$end[hit$ri])];fwrite(z,paste0(out,rbp,'_eligible_peak_context.tsv.gz'),sep='\t');elig[[rbp]]=data.table(RBP=rbp,post_conversion_N=nrow(d),null_eligible_N=nrow(z),excluded_no_same_strand_genic_segment=nrow(d)-nrow(z),seed=260923,permutations=perm)
 for(t in c('donor','acceptor')){
  dd=nearest(z$center,z$chrom,z$strand,t);counts=tabulate(floor((dd[dd>=-1000 & dd<1000]+1000)/10)+1L,200);nul=matrix(0,200,perm);nz=matrix(0,7,perm)
  zonebounds=list(exon_proximal=if(t=='donor')c(-50,0) else c(0,50),intron_proximal=if(t=='donor')c(0,50) else c(-50,0),distal_left=c(-1000,-250),distal_right=c(250,1000),MSI2_derived_extremum=if(t=='donor')c(-10,0) else c(0,20),within50=c(-50,50),within250=c(-250,250))
  zcount=function(v)vapply(zonebounds,function(b)sum(v>=b[1]&v<b[2]),numeric(1));obsz=zcount(dd)
  for(it in seq_len(perm)){rp=z$null_start+floor(runif(nrow(z))*(z$null_end-z$null_start));nd=nearest(rp,z$chrom,z$strand,t);nul[,it]=tabulate(floor((nd[nd>=-1000 & nd<1000]+1000)/10)+1L,200);nz[,it]=zcount(nd)}
  ex=rowMeans(nul);lo=apply(nul,1,quantile,.025);hi=apply(nul,1,quantile,.975)
  prof=data.table(RBP=rbp,boundary=t,bin_start=seq(-1000,990,10),bin_end=seq(-990,1000,10),bin_center=seq(-995,995,10),eligible_N=nrow(z),observed_count=counts,observed_fraction=counts/nrow(z),expected_count=ex,expected_fraction=ex/nrow(z),null_low_fraction=lo/nrow(z),null_high_fraction=hi/nrow(z),observed_expected=ifelse(ex>0,counts/ex,NA_real_),null_low_OE=ifelse(ex>0,lo/ex,NA_real_),null_high_OE=ifelse(ex>0,hi/ex,NA_real_),empirical_p_enrichment=(1+rowSums(nul>=counts))/(perm+1),empirical_p_depletion=(1+rowSums(nul<=counts))/(perm+1),permutations=perm,seed=260923)
  profiles[[paste(rbp,t)]]=prof;saveRDS(nul,paste0(out,rbp,'_',t,'_null_bin_counts.rds'))
  zones[[paste(rbp,t)]]=data.table(RBP=rbp,boundary=t,zone=names(zonebounds),zone_start=vapply(zonebounds,`[`,numeric(1),1),zone_end=vapply(zonebounds,`[`,numeric(1),2),observed_peaks=obsz,expected_peaks=rowMeans(nz),enrichment=obsz/rowMeans(nz),null_low=apply(nz,1,quantile,.025),null_high=apply(nz,1,quantile,.975),empirical_p=(1+rowSums(nz>=obsz))/(perm+1),eligible_N=nrow(z))
  ll=land[type==t];lg=GRanges(ll$chromosome,IRanges(ll$anchor_0based+1,width=1),ll$strand)
  for(w in c(50,250)){wg=GRanges(d$chrom,IRanges(pmax(1,d$center-w+1),d$center+w+1),d$strand);hh=suppressWarnings(findOverlaps(wg,lg));prox[[paste(rbp,t,w)]]=data.table(RBP=rbp,boundary=t,window_nt=w,all_annotated_sites=nrow(ll),sites_with_peak=length(unique(subjectHits(hh))),fraction_sites_with_peak=length(unique(subjectHits(hh)))/nrow(ll),all_peaks=nrow(d),peaks_near_site=length(unique(queryHits(hh))),fraction_peaks_near_site=length(unique(queryHits(hh)))/nrow(d))}
 }
}
pr=rbindlist(profiles);pr[,q_BH:=p.adjust(empirical_p_enrichment,'BH')];fwrite(pr,paste0(out,'splice_bin_profiles.tsv'),sep='\t');fwrite(pr,paste0(out,'splice_enrichment_vs_background.tsv'),sep='\t');fwrite(rbindlist(prox),paste0(out,'splice_proximity_summary.tsv'),sep='\t');fwrite(rbindlist(zones),paste0(out,'splice_zone_enrichment.tsv'),sep='\t');fwrite(rbindlist(elig),paste0(out,'background_eligibility.tsv'),sep='\t')
pr[,RBP:=factor(RBP,levels=c('MSI2','QKI','PUM2','ELAVL1'))]
plot=function(dat){ggplot(dat,aes(bin_center,observed_expected))+geom_ribbon(aes(ymin=null_low_OE,ymax=null_high_OE),fill='grey80')+geom_hline(yintercept=1,lty=2)+geom_vline(xintercept=0,color='grey40')+geom_line(color='#226778')+facet_grid(RBP~boundary)+theme_bw()+labs(x='Transcript-oriented distance to boundary (nt)',y='Observed / matched-background peak fraction',title='Called sites near splice boundaries',subtitle='Nearest same-strand boundary; 10-nt bins; 500 within-gene/region permutations')}
savep(plot(pr[abs(bin_center)<250]),'external_rbp_splice_comparison');savep(plot(pr),'external_rbp_splice_comparison_1000')
for(t in c('donor','acceptor'))savep(plot(pr[boundary==t]),paste0(t,'_profiles'),7,11)
savep(ggplot(pr,aes(bin_center,observed_fraction))+geom_ribbon(aes(ymin=null_low_fraction,ymax=null_high_fraction),fill='grey80')+geom_line(color='#226778')+facet_grid(RBP~boundary)+theme_bw()+labs(x='Distance(nt)',y='Fraction of eligible peaks per10nt'),'normalized_peak_density')
